// Событие приходит из бэкенда Navi: POST /ticket
// { event: 'ticket.created', data: { role, question, contact, user } }
const body = $input.first().json.body ?? $input.first().json;
const d = body.data ?? {};

const ROLE_RU = {
  guest: 'Гость',
  student: 'Студент',
  teacher: 'Преподаватель',
  admin: 'Администратор',
};

// Куда направить заявку — зависит от роли автора
const ROUTE = {
  student: 'Учебный отдел',
  teacher: 'Кафедра',
  admin: 'Канцелярия',
  guest: 'Приёмная комиссия',
};

const role = d.role || 'guest';
const ticketId = 'T-' + Date.now().toString(36).toUpperCase();

const text = [
  '🎓 *Новая заявка через Navi*',
  '',
  '*Номер:* `' + ticketId + '`',
  '*Роль:* ' + (ROLE_RU[role] || role),
  '*Адресат:* ' + (ROUTE[role] || '—'),
  '*Пользователь:* ' + (d.user || 'не указан'),
  '',
  '*Вопрос:*',
  d.question || '—',
].join('\n');

return [{ json: { ticketId, role, route: ROUTE[role] || '', text, raw: d } }];
